import path from 'node:path';
import { compareText, stableJson, type GolemGeneratorEntry, type GolemProfile } from '@exprtlabs/golem/generator-api';

/** A tiny extension generator: it writes one model source whose fields come from its options. Its imports are public. */
export const apiVersion = 1;

interface AcmeContext {
  readonly output: string;
  readonly options: { readonly fields: Readonly<Record<string, string>> };
  readonly profile: GolemProfile;
}

export const generate: GolemGeneratorEntry<AcmeContext>['generate'] = (context) => {
  const { fields } = context.options;
  const lines = Object.keys(fields).sort(compareText).map((name) => `  ${name}: ${fields[name]};`);
  const content = `/* Generated by @fixture/extension. Do not edit. */
/* options: ${stableJson(context.options)} */
/* profile: ${JSON.stringify({ mobx: context.profile.mobx, validation: context.profile.validation })} */
import type { IModel } from '@exprtlabs/golem/model';
import { TCardBaseModel } from './card.model.generated.js';
export type TCard = IModel<{
${lines.join('\n')}
}>;
export class Card extends TCardBaseModel {}
`;
  return { artifacts: [{ path: path.join(context.output, 'card.model.ts'), content }], manifestPaths: [], watchInputs: [] };
};
